Source: https://github.com/thunderbird/thunderbird-desktop/commit/a9ca04f4355ad2ec3b71d683cb340f293d13c076

Coverage: Actual diff inspected; related inverse/reland duplicate hunks checked as a chain.
Full four-file diff. Synthetic view total uses numMsgsInView rather than visible rowCount. Header selection lifecycle moved out of view creation; loaded messages and removal update counts. Deletion decrements actual selected message header count. Review rejected timeout fixes and a broader onFolderSelected trigger. Accepted with known filtered synthetic deletion edge discussed, so do not claim every edge solved.

commit a9ca04f4355ad2ec3b71d683cb340f293d13c076
Author:     welpy-cw <h.w.forms@arcor.de>
AuthorDate: Fri May 31 13:38:25 2024 +0300
Commit:     welpy-cw <h.w.forms@arcor.de>
CommitDate: Fri May 31 13:38:25 2024 +0300

    Bug 1896899 - Fix thread pane header's message count in synthetic views. r=darktrojan,mkmelin


    Update the message count when all messages have been loaded and when a message has been deleted.

    Differential Revision: https://phabricator.services.mozilla.com/D210487

diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index 31f3d8afbd6..41dfc0b2c92 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -2465,13 +2465,13 @@ var folderPane = {
       }

       gViewWrapper.open(gFolder);
-
       // At this point `dbViewWrapperListener.onCreatedView` gets called,
       // setting up gDBView and scrolling threadTree to the right end.

       threadPane.updateListRole(
         !gViewWrapper?.showThreaded && !gViewWrapper?.showGroupedBySort
       );
+      threadPaneHeader.onFolderSelected();
     }

     this._updateStatusQuota();
@@ -3749,7 +3749,8 @@ var threadPaneHeader = {
   },

   /**
-   * Update the header data when the selected folder changes.
+   * Update the header data when the selected folder changes, or when a
+   * synthetic view is created.
    */
   onFolderSelected() {
     // Bail out if the pane is hidden as we don't need to update anything.
@@ -3767,25 +3768,20 @@ var threadPaneHeader = {

     this.folderName.textContent = gFolder?.abbreviatedName ?? document.title;
     this.folderName.title = gFolder?.prettyName ?? document.title;
-    document.l10n.setAttributes(
-      this.folderCount,
-      "thread-pane-folder-message-count",
-      { count: gFolder?.getTotalMessages(false) || gDBView?.rowCount || 0 }
+    this.updateMessageCount(
+      gFolder?.getTotalMessages(false) || gDBView?.numMsgsInView || 0
     );
-
     this.folderName.hidden = false;
     this.folderCount.hidden = false;
   },

   /**
-   * Update the total message count in the header if the value changed for the
-   * currently selected folder.
+   * Update the total message count in the header.
    *
-   * @param {nsIMsgFolder} folder - The folder updating the count.
    * @param {integer} newValue
    */
-  updateFolderCount(folder, newValue) {
-    if (!gFolder || !folder || this.isHidden || folder.URI != gFolder.URI) {
+  updateMessageCount(newValue) {
+    if (this.isHidden) {
       return;
     }

@@ -5801,7 +5797,11 @@ var folderListener = {
       gViewWrapper?.close(true);
     }
   },
-  onMessageRemoved() {},
+  onMessageRemoved() {
+    if (gViewWrapper?.isSynthetic) {
+      window.threadPaneHeader.updateMessageCount(gDBView.numMsgsInView);
+    }
+  },
   onFolderPropertyChanged() {},
   onFolderIntPropertyChanged(folder, property, oldValue, newValue) {
     switch (property) {
@@ -5828,7 +5828,9 @@ var folderListener = {
           break;
         }
         folderPane.changeTotalCount(folder, newValue);
-        threadPaneHeader.updateFolderCount(folder, newValue);
+        if (gFolder && folder?.URI == gFolder.URI) {
+          threadPaneHeader.updateMessageCount(newValue);
+        }
         break;
     }
   },
diff --git a/mail/base/content/mailCommon.js b/mail/base/content/mailCommon.js
index daa318a4d1b..8e6e473e8d8 100644
--- a/mail/base/content/mailCommon.js
+++ b/mail/base/content/mailCommon.js
@@ -1007,7 +1007,6 @@ var dbViewWrapperListener = {
     window.threadPane.setTreeView(gViewWrapper.dbView);
     window.threadPane.restoreSortIndicator();
     window.threadPane.restoreThreadState(gViewWrapper.isSingleFolder);
-    window.threadPaneHeader.onFolderSelected();
     window.threadPane.isFirstScroll = true;
     window.threadPane.scrollDetected = false;
     window.threadPane.scrollToLatestRowIfNoSelection();
@@ -1083,6 +1082,13 @@ var dbViewWrapperListener = {
         window.threadPane.scrollToLatestRowIfNoSelection();
       }
     }
+    // To be consistent with the behavior in saved searches, update the message
+    // count in synthetic views when a quick filter term is entered or cleared.
+    if (gViewWrapper.isSynthetic) {
+      window.threadPaneHeader.updateMessageCount(
+        gViewWrapper.dbView.numMsgsInView
+      );
+    }
     window.quickFilterBar?.onMessagesChanged();
   },
   onMailViewChanged() {
diff --git a/mailnews/base/src/nsMsgSearchDBView.cpp b/mailnews/base/src/nsMsgSearchDBView.cpp
index ce8f26f34ba..1cbcc3591b3 100644
--- a/mailnews/base/src/nsMsgSearchDBView.cpp
+++ b/mailnews/base/src/nsMsgSearchDBView.cpp
@@ -844,8 +844,11 @@ NS_IMETHODIMP nsMsgSearchDBView::ApplyCommandToIndices(
 nsresult nsMsgSearchDBView::DeleteMessages(
     nsIMsgWindow* window, nsTArray<nsMsgViewIndex> const& selection,
     bool deleteStorage) {
-  nsresult rv = GetFoldersAndHdrsForSelection(selection);
+  uint32_t hdrCount = 0;
+  nsresult rv = GetFoldersAndHdrsForSelection(selection, &hdrCount);
   NS_ENSURE_SUCCESS(rv, rv);
+  m_totalMessagesInView -= hdrCount;
+
   if (mDeleteModel != nsMsgImapDeleteModels::MoveToTrash) deleteStorage = true;

   if (mDeleteModel != nsMsgImapDeleteModels::IMAPDelete) m_deletingRows = true;
@@ -916,7 +919,7 @@ nsresult nsMsgSearchDBView::PartitionSelectionByFolder(
 }

 nsresult nsMsgSearchDBView::GetFoldersAndHdrsForSelection(
-    nsTArray<nsMsgViewIndex> const& selection) {
+    nsTArray<nsMsgViewIndex> const& selection, uint32_t* hdrCount) {
   nsresult rv = NS_OK;
   mCurIndex = 0;
   m_uniqueFoldersSelected.Clear();
@@ -925,6 +928,9 @@ nsresult nsMsgSearchDBView::GetFoldersAndHdrsForSelection(
   AutoTArray<RefPtr<nsIMsgDBHdr>, 1> messages;
   rv = GetHeadersFromSelection(selection, messages);
   NS_ENSURE_SUCCESS(rv, rv);
+  if (hdrCount) {
+    *hdrCount = messages.Length();
+  }

   // Build unique folder list based on headers selected by the user.
   for (nsIMsgDBHdr* hdr : messages) {
